/* HEXA BATTLEGROUNDS setup — PART 15 OF 19. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-bughunt-2', 'bughunt', 'mission', 'Bug Hunt', 'tech', 1, array['stg','testing','office']::text[], 'A test failed in the STG lab. Find the buggy line and the value that fixes it.', '{"scout":{"title":"Source code","body":"1  names = [\"Asha\", \"Ben\", \"Chen\"]\n2  last = names[3]\n3  print(last)","mono":true},"decoder":{"title":"Test log","body":"Test log: crashed with \"index out of range\".\nRule: list positions start at 0."},"intel":{"title":"Requirement","body":"Spec: print the LAST name. Report the bug line and the index that should be used."}}'::jsonb, '[{"label":"Bug line number","accept":["2"]},{"label":"Correct value","accept":["2"]}]'::jsonb, false, 3, 200, 'Compare what the code does with what the requirement says.', 'Index 3 does not exist; the last item is at index 2.', null, 25, 'published'), ('mission-boardroom-0', 'boardroom', 'mission', 'Boardroom Mole', 'logic', 2, array['boardroom']::text[], 'Squad 00 planted a mole in the boardroom. Work out the seating and name the mole.', '{"scout":{"title":"Boardroom seating chart","body":"Round table, seats 1–6 clockwise.\nSeats directly opposite: 1–4, 2–5, 3–6.\nSeat 3: LEGAL\nSeat 5: OPS\nSeats 1, 2, 4, 6: unknown","mono":true},"decoder":{"title":"Seating rules","body":"Remaining guests: CTO, CFO, HR, SALES.\n• CTO sits directly opposite LEGAL.\n• HR sits directly next to OPS.\n• SALES is not in seat 1."},"intel":{"title":"Mole intel","body":"The mole sits directly opposite the CFO. Submit the mole''s role."}}'::jsonb, '[{"label":"Mole''s role","accept":["HR","HUMANRESOURCES"]}]'::jsonb, false, 3, 220, 'Place the CTO first, then HR.', 'CTO 6, HR 4, Sales 2, CFO 1 → opposite seat 1 is seat 4: HR.', null, 25, 'published'), ('mission-boardroom-1', 'boardroom', 'mission', 'Boardroom Mole', 'logic', 2, array['boardroom']::text[], 'Squad 00 planted a mole in the boardroom. Work out the seating and name the mole.', '{"scout":{"title":"Boardroom seating chart","body":"Round table, seats 1–6 clockwise.\nSeats directly opposite: 1–4, 2–5, 3–6.\nSeat 3: LEGAL\nSeat 5: OPS\nSeats 1, 2, 4, 6: unknown","mono":true},"decoder":{"title":"Seating rules","body":"Remaining guests: CTO, CFO, HR, SALES.\n• CTO sits directly opposite LEGAL.\n• HR sits directly next to OPS.\n• SALES is not in seat 1."},"intel":{"title":"Mole intel","body":"The mole sits directly opposite SALES. Submit the mole''s role."}}'::jsonb, '[{"label":"Mole''s role","accept":["OPS","OPERATIONS"]}]'::jsonb, false, 3, 220, 'Place the CTO first, then HR.', 'CTO 6, HR 4, Sales 2, CFO 1 → opposite seat 2 is seat 5: OPS.', null, 25, 'published'), ('mission-hr-0', 'scheduler', 'mission', 'Room Booking Crisis', 'logic', 1, array['hr','office']::text[], 'HR needs a 1-hour room for an urgent team huddle. Find the right booking.', '{"scout":{"title":"Room availability","body":"         9:00   10:00   11:00\nRoom A   free   busy    free\nRoom B   free   busy    free\nRoom C   free   free    busy\nRoom D   busy   free    free","mono":true},"decoder":{"title":"Attendee constraints","body":"• The huddle needs a screen: only Rooms B and D have one.\n• The designer cannot attend at 9:00."},"intel":{"title":"Booking policy","body":"Book the EARLIEST slot that works.\nSubmit as room letter + hour, e.g. A9."}}'::jsonb, '[{"label":"Booking","accept":["D10"]}]'::jsonb, false, 3, 180, 'Rule out 9:00 first.', 'Only B/D have screens, 9:00 is out, B is busy at 10 → D10.', null, 25, 'published'), ('mission-hr-1', 'scheduler', 'mission', 'Room Booking Crisis', 'logic', 1, array['hr','office']::text[], 'HR needs a 1-hour room for an urgent team huddle. Find the right booking.', '{"scout":{"title":"Room availability","body":"         9:00   10:00   11:00\nRoom A   free   free    busy\nRoom B   free   busy    free\nRoom C   busy   free    free\nRoom D   busy   busy    free","mono":true},"decoder":{"title":"Attendee constraints","body":"• The huddle needs a screen: only Rooms B and D have one.\n• The designer cannot attend at 9:00."},"intel":{"title":"Booking policy","body":"Book the EARLIEST slot that works. If two rooms tie, pick Room B (closest to HR).\nSubmit as room letter + hour, e.g. A9."}}'::jsonb, '[{"label":"Booking","accept":["B11"]}]'::jsonb, false, 3, 180, 'Check 10:00 for B and D first.', 'At 10 both B and D are busy; at 11 both are free → tie → B11.', null, 25, 'published'), ('battle-triad-200', 'triad', 'battle', 'Tech Triad', 'tech', 1, array['duel_pistol']::text[], 'Each teammate holds one tech question. Collect all three numbers and enter them in order.', '{"scout":{"title":"Code fragment 1 of 3","body":"Ctrl + which letter usually means Undo? Give its position in the alphabet (A=1).\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"HTTP status code for \"Internal Server Error\"?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"Binary 1010 equals which decimal number?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Part 1 (Scout)","accept":["26"]},{"label":"Part 2 (Decoder)","accept":["500"]},{"label":"Part 3 (Intel)","accept":["10"]}]'::jsonb, false, 3, 90, 'The three numbers have 2, 3, 2 digits.', 'Ctrl + which letter usually means Undo? Give its position in the alphabet (A=1). → 26 | HTTP status code for "Internal Server Error"? → 500 | Binary 1010 equals which decimal number? → 10', null, 25, 'published'), ('battle-triad-201', 'triad', 'battle', 'Tech Triad', 'tech', 1, array['duel_pistol']::text[], 'Each teammate holds one tech question. Collect all three numbers and enter them in order.', '{"scout":{"title":"Code fragment 1 of 3","body":"Binary 1000 equals which decimal number?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"Function key that refreshes most browser pages: F?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"HTTP status code for \"OK\"?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Part 1 (Scout)","accept":["8"]},{"label":"Part 2 (Decoder)","accept":["5"]},{"label":"Part 3 (Intel)","accept":["200"]}]'::jsonb, false, 3, 90, 'The three numbers have 1, 1, 3 digits.', 'Binary 1000 equals which decimal number? → 8 | Function key that refreshes most browser pages: F? → 5 | HTTP status code for "OK"? → 200', null, 25, 'published'), ('battle-triad-202', 'triad', 'battle', 'Tech Triad', 'tech', 1, array['duel_pistol']::text[], 'Each teammate holds one tech question. Collect all three numbers and enter them in order.', '{"scout":{"title":"Code fragment 1 of 3","body":"How many hexadecimal digits exist (0 to F)?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"Binary 1000 equals which decimal number?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"Function key that refreshes most browser pages: F?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Part 1 (Scout)","accept":["16"]},{"label":"Part 2 (Decoder)","accept":["8"]},{"label":"Part 3 (Intel)","accept":["5"]}]'::jsonb, false, 3, 90, 'The three numbers have 2, 1, 1 digits.', 'How many hexadecimal digits exist (0 to F)? → 16 | Binary 1000 equals which decimal number? → 8 | Function key that refreshes most browser pages: F? → 5', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('battle-triad-203', 'triad', 'battle', 'Tech Triad', 'tech', 1, array['duel_pistol']::text[], 'Each teammate holds one tech question. Collect all three numbers and enter them in order.', '{"scout":{"title":"Code fragment 1 of 3","body":"Hexadecimal F equals which decimal number?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"Function key that refreshes most browser pages: F?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"HTTP status code for \"Forbidden\"?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Part 1 (Scout)","accept":["15"]},{"label":"Part 2 (Decoder)","accept":["5"]},{"label":"Part 3 (Intel)","accept":["403"]}]'::jsonb, false, 3, 90, 'The three numbers have 2, 1, 3 digits.', 'Hexadecimal F equals which decimal number? → 15 | Function key that refreshes most browser pages: F? → 5 | HTTP status code for "Forbidden"? → 403', null, 25, 'published'), ('battle-triad-204', 'triad', 'battle', 'Tech Triad', 'tech', 1, array['duel_pistol']::text[], 'Each teammate holds one tech question. Collect all three numbers and enter them in order.', '{"scout":{"title":"Code fragment 1 of 3","body":"How many bytes are in one kibibyte (KiB)?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"In most programming languages, the index of the first array element is?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"How many bits are in one byte?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Part 1 (Scout)","accept":["1024"]},{"label":"Part 2 (Decoder)","accept":["0"]},{"label":"Part 3 (Intel)","accept":["8"]}]'::jsonb, false, 3, 90, 'The three numbers have 4, 1, 1 digits.', 'How many bytes are in one kibibyte (KiB)? → 1024 | In most programming languages, the index of the first array element is? → 0 | How many bits are in one byte? → 8', null, 25, 'published'), ('battle-triad-205', 'triad', 'battle', 'Tech Triad', 'tech', 1, array['duel_pistol']::text[], 'Each teammate holds one tech question. Collect all three numbers and enter them in order.', '{"scout":{"title":"Code fragment 1 of 3","body":"HTTP status code for \"Forbidden\"?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"Hexadecimal F equals which decimal number?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"Hexadecimal 1A equals which decimal number?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Part 1 (Scout)","accept":["403"]},{"label":"Part 2 (Decoder)","accept":["15"]},{"label":"Part 3 (Intel)","accept":["26"]}]'::jsonb, false, 3, 90, 'The three numbers have 3, 2, 2 digits.', 'HTTP status code for "Forbidden"? → 403 | Hexadecimal F equals which decimal number? → 15 | Hexadecimal 1A equals which decimal number? → 26', null, 25, 'published'), ('battle-keypad-200', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_pistol']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 9, 8, 3, 5\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"ODD digits come first (smallest to largest), then EVEN digits (largest to smallest)."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: swap the 1st and last digits before entering."}}'::jsonb, '[{"label":"Access code","accept":["8593"]}]'::jsonb, false, 3, 90, 'The code has 4 digits.', 'Ordered digits 3598, after the wiring fault 8593.', null, 25, 'published'), ('battle-keypad-201', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_pistol']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 7, 2, 4, 3\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from SMALLEST to LARGEST digit."},"intel":{"title":"Maintenance report","body":"The panel adds 1 to the LAST digit (9 becomes 0)."}}'::jsonb, '[{"label":"Access code","accept":["2348"]}]'::jsonb, false, 3, 90, 'The code has 4 digits.', 'Ordered digits 2347, after the wiring fault 2348.', null, 25, 'published'), ('battle-keypad-202', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_pistol']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 1, 5, 7, 4\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from LARGEST to SMALLEST digit."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: swap the 1st and last digits before entering."}}'::jsonb, '[{"label":"Access code","accept":["1547"]}]'::jsonb, false, 3, 90, 'The code has 4 digits.', 'Ordered digits 7541, after the wiring fault 1547.', null, 25, 'published'), ('battle-keypad-203', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_pistol']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 9, 3, 6, 2\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from SMALLEST to LARGEST digit."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: the 2nd and 3rd digits are swapped."}}'::jsonb, '[{"label":"Access code","accept":["2639"]}]'::jsonb, false, 3, 90, 'The code has 4 digits.', 'Ordered digits 2369, after the wiring fault 2639.', null, 25, 'published'), ('battle-keypad-300', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_smg']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 9, 3, 4\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from LARGEST to SMALLEST digit."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: the 2nd and 3rd digits are swapped."}}'::jsonb, '[{"label":"Access code","accept":["934"]}]'::jsonb, false, 3, 50, 'The code has 3 digits.', 'Ordered digits 943, after the wiring fault 934.', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at =